mapper.insert:
insert into lecture (
	lecture_no, lecture_title, lecture_category,
	lecture_duration, lecture_price, lecture_type
)
values(
	#{lectureNo}, #{lectureTitle}, #{lectureCategory},
	#{lectureDuration}, #{lecturePrice}, #{lectureType}
)

mapper.select:
select * from (
	select rownum rn, TMP.* from (
		select * from lecture



		where lecture_no < #{lastLectureNo}


		order by lecture_no desc
	)TMP
) where rn between 1 and #{size}
